CREATE OR REPLACE FUNCTION public.icash_capture_buyer_title_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;turns jsonb;quote text;screen uuid;
begin
 if new.direction<>'incoming' or new.state<>'received' then return new;end if;
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id and party='buyer';if not found then return new;end if;
 select screening_id into screen from public.icash_deal_files where id=t.deal_id and account_id=t.account_id;if screen is null then return new;end if;
 select jsonb_agg(jsonb_build_object('role',case when direction='incoming' then 'user' else 'agent' end,'message',body) order by created_at,id) into turns
 from (select id,direction,body,created_at from public.icash_text_messages
  where thread_id=t.id and account_id=t.account_id and created_at between new.created_at-interval '1 day' and new.created_at
  and (id=new.id or direction='incoming' and state='received' or direction='outgoing' and state in ('accepted','delivered') and provider_id is not null)
  order by created_at desc,id desc limit 12) messages;
 quote:=public.icash_buyer_title_quote(turns);
 if quote is null or position(btrim(new.body) in quote)=0 then return new;end if;
 insert into public.icash_buyer_viewing_requests(account_id,deal_id,screening_id,thread_id,source,source_id,quote,title_quote,timezone,kind)
 values(t.account_id,t.deal_id,screen,t.id,'text',new.id,quote,quote,t.timezone,'title_company')
 on conflict(source,source_id) do update set title_quote=excluded.title_quote
 where icash_buyer_viewing_requests.state='needs_confirmation' and icash_buyer_viewing_requests.title_quote is null;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_capture_seller_negative_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if TG_TABLE_NAME='icash_text_messages' then
  if new.direction='incoming' and new.state='received' and (TG_OP='INSERT' or old.thread_id is distinct from new.thread_id or old.state is distinct from new.state) then perform public.icash_apply_seller_response('sms',new.id);end if;
 elsif TG_TABLE_NAME='icash_live_conversations' then
  if new.party='seller' and new.state='complete' and (TG_OP='INSERT' or old.state is distinct from new.state) then perform public.icash_apply_seller_response('call',new.id);end if;
 elsif TG_TABLE_NAME='call_history' then perform public.icash_apply_seller_response('inbound_call',new.session_id);
 elsif TG_TABLE_NAME='icash_deal_emails' and new.direction='incoming' and new.state='received' then perform public.icash_apply_seller_response('email',new.id);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_message_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;r public.icash_sms_routes;v jsonb;pair_sender text;pair_recipient text;
begin
 if TG_OP='UPDATE' then
  if row(new.thread_id,new.account_id,new.direction,new.route_revision) is distinct from row(old.thread_id,old.account_id,old.direction,old.route_revision) then
   if not (old.thread_id is null and new.thread_id is not null and old.state='needs_review' and new.state='received'
    and row(new.account_id,new.direction,new.route_revision,new.body,new.created_at,new.event_id,new.provider_id,new.attachments)
      is not distinct from row(old.account_id,old.direction,old.route_revision,old.body,old.created_at,old.event_id,old.provider_id,old.attachments)
    and public.icash_sms_owner_reply_resolution_current(old.id,new.account_id,new.thread_id,new.route_revision))
   then raise exception 'SMS message route is immutable';end if;
  end if;
  return new;
 end if;
 -- Provider retries and repeated queue requests must not advance routing state.
 if exists(select 1 from public.icash_text_messages m where (new.event_id is not null and m.event_id=new.event_id) or (new.provider_id is not null and m.provider_id=new.provider_id) or (new.request_key is not null and m.request_key=new.request_key)) then return null;end if;
 if new.thread_id is not null then
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id;
 if not found then raise exception 'SMS message account mismatch';end if;
 pair_sender:=t.sender;pair_recipient:=t.recipient;
 elsif new.direction='incoming' then
 select payload->'data' into v from public.icash_text_events where id=new.event_id;
 pair_sender:=v->>'to';pair_recipient:=v->>'from';
 end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform pg_advisory_xact_lock(hashtextextended(pair_recipient,74));
 select * into r from public.icash_sms_routes where sender=pair_sender and recipient=pair_recipient for update;
 if new.direction='outgoing' then
  if r.account_id is distinct from new.account_id or (r.needs_review and not public.icash_seller_clarification_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision) and not (cardinality(new.asset_ids)=0 and new.attachments='[]'::jsonb and public.icash_fresh_intake_opener_current(new.account_id,new.thread_id,new.request_key,new.body,r.revision))) or t.retired_at is not null then raise exception 'SMS property routing requires review';end if;
 elsif r.account_id is not null then
  -- Any incoming message invalidates queued decisions; ambiguous replies hold all
  -- properties on the pair until an explicit property reply or human review.
  update public.icash_sms_routes set revision=revision+1,needs_review=(new.thread_id is null) where sender=pair_sender and recipient=pair_recipient returning * into r;
  if new.thread_id is null then new.account_id:=r.account_id;new.state:='needs_review';end if;
 end if;
 new.route_revision:=r.revision;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_learning_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb;account uuid;ignored text[]:=array['updated_at','next_poll_at','poll_attempts','next_attempt_at','attempts','lease_until','lease_token'];
begin
 -- Scheduler bookkeeping is not a new outcome or a workspace state change.
 if tg_table_name='icash_discovery_configs' then ignored:=ignored||array['next_run_at'];end if;
 if tg_op='UPDATE' and (to_jsonb(new)-ignored) is not distinct from (to_jsonb(old)-ignored) then return new;end if;
 item:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 account:=case when tg_table_name='icash_accounts' then (item->>'id')::uuid else (item->>'account_id')::uuid end;
 if account is null and item->>'deal_id' is not null then select account_id into account from public.icash_deal_files where id=(item->>'deal_id')::uuid;end if;
 if account is not null and exists(select 1 from public.icash_accounts where id=account) then
  insert into public.icash_workspace_revisions(account_id) values(account) on conflict(account_id) do update set revision=public.icash_workspace_revisions.revision+1,changed_at=now();
  insert into public.icash_learning_queue(account_id) values(account) on conflict(account_id) do update
   set due_at=least(public.icash_learning_queue.due_at,now()+interval '1 minute'),generation=public.icash_learning_queue.generation+1;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.icash_meta_cancel_followups()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare lead uuid;reason text:='meta_followup_stopped';
begin
 if TG_TABLE_NAME='icash_meta_leads' then
  if new.response_at is null and new.address_confirmed_at is null and new.declined_at is null and not new.paused then return new;end if;
  lead:=new.lead_id;
  if new.paused and new.response_at is null and new.declined_at is null and new.address_confirmed_at is null then reason:='meta_lead_paused';end if;
 else
  if new.direction<>'incoming' or new.state<>'received' then return new;end if;
  select t.seller_intake_id into lead from public.icash_text_threads t where t.id=new.thread_id and t.account_id=new.account_id;
 end if;
 if lead is null then return new;end if;
 update public.icash_text_messages msg set state='cancelled',updated_at=now()
 from public.icash_meta_lead_messages mm where mm.message_id=msg.id and mm.lead_id=lead
  and mm.purpose in ('followup_1','followup_2') and msg.state='ready' and msg.provider_id is null;
 update public.icash_voice_jobs j set state='held',outcome=reason,updated_at=now()
 where j.meta_followup_lead_id=lead and j.state in ('ready','issued') and j.provider_call_sid is null and j.conversation_id is null
  and not exists(select 1 from public.icash_operation_spend o where o.operation_key='voice:'||j.id);
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_meta_observe_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare lead uuid;body text:=lower(trim(new.body));
begin
 select m.lead_id into lead from public.icash_meta_leads m join public.icash_text_threads t on t.seller_intake_id=m.lead_id and (t.account_id=m.account_id or exists(select 1 from public.icash_seller_matches sm where sm.lead_id=m.lead_id and sm.account_id=t.account_id and sm.screening_id=(select d.screening_id from public.icash_deal_files d where d.id=t.deal_id and d.account_id=t.account_id))) where t.id=new.thread_id and t.account_id=new.account_id;
 if lead is null then return new;end if;
 if new.direction='outgoing' and new.provider_id is not null and new.state in ('accepted','delivered') then
  update public.icash_meta_leads set first_outreach_at=coalesce(first_outreach_at,now()) where lead_id=lead and account_id=new.account_id;
 elsif new.direction='incoming' and new.state='received' then
  if public.icash_seller_response_disposition(new.body)='opt_out'
   or public.icash_seller_direct_response_match(replace(body,'’',chr(39)),'\m(text (me )?only|only text)\M') then
   update public.icash_meta_leads set voice_paused=true where lead_id=lead;
   update public.icash_voice_jobs j set state='held',outcome='seller_requested_text_only',updated_at=now() from public.icash_contact_permissions p where p.id=j.permission_id and p.seller_intake_id=lead and p.account_id=new.account_id and j.account_id=new.account_id and j.state in ('ready','issued') and j.provider_call_sid is null and j.conversation_id is null and not exists(select 1 from public.icash_operation_spend o where o.operation_key='voice:'||j.id);
  end if;
  if public.icash_seller_response_disposition(new.body) in ('opt_out','declined') then
   update public.icash_meta_leads set declined_at=coalesce(declined_at,now()),paused=true where lead_id=lead and account_id=new.account_id;
  elsif body ~ '\m(human|real person|speak to someone|talk to someone)\M' then
   update public.icash_meta_leads set paused=true,response_at=coalesce(response_at,new.created_at),response_channel=coalesce(response_channel,'sms') where lead_id=lead and account_id=new.account_id;
   update public.icash_seller_intakes set hold_reason='Seller requested a person; automatic follow-up paused' where id=lead and exists(select 1 from public.icash_meta_leads own where own.lead_id=lead and own.account_id=new.account_id);
  elsif length(body)>=2 and body !~ '\m(automatic reply|auto.reply|delivery|voicemail|out of office)\M' then
   update public.icash_meta_leads set response_at=coalesce(response_at,new.created_at),response_channel=coalesce(response_channel,'sms') where lead_id=lead and account_id=new.account_id;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_observe_seller_opener()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sent_at timestamptz;first_reply timestamptz;declined boolean;
begin
 if new.direction='outgoing' then
  update public.icash_seller_opener_assignments set message_id=new.id,
   delivered_at=case when new.state='delivered' then coalesce(delivered_at,new.last_delivery_at,now()) else delivered_at end
  where thread_id=new.thread_id and account_id=new.account_id and body=new.body and (message_id is null or message_id=new.id);
  if new.state='delivered' then
   -- The provider confirmed this send succeeded. Replies after send creation can
   -- precede the delivery webhook; keep their actual timestamps, never synthesize one.
   select min(m.created_at),coalesce(bool_or(m.body ~* '(^\s*(stop|unsubscribe|cancel|end|quit)\s*$|do not (text|contact)|don''t (text|contact)|not interested)'),false)
    into first_reply,declined from public.icash_text_messages m
    where m.thread_id=new.thread_id and m.account_id=new.account_id and m.direction='incoming' and m.state='received' and m.created_at>=new.created_at;
   update public.icash_seller_opener_assignments set first_reply_at=case when first_reply is null then first_reply_at else least(first_reply_at,first_reply) end,opted_out=opted_out or declined
    where message_id=new.id and account_id=new.account_id;
  end if;
 elsif new.direction='incoming' and new.state='received' then
  select m.created_at into sent_at from public.icash_seller_opener_assignments a join public.icash_text_messages m on m.id=a.message_id and m.account_id=a.account_id
   where a.thread_id=new.thread_id and a.account_id=new.account_id and a.delivered_at is not null;
  if sent_at is not null and new.created_at>=sent_at then
   update public.icash_seller_opener_assignments set first_reply_at=least(first_reply_at,new.created_at),opted_out=opted_out or new.body ~* '(^\s*(stop|unsubscribe|cancel|end|quit)\s*$|do not (text|contact)|don''t (text|contact)|not interested)'
    where thread_id=new.thread_id and account_id=new.account_id;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_observe_seller_recovery_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;reason text;
begin
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id and party='seller';if not found then return new;end if;
 if new.direction='incoming' and new.state='received' and tg_op='INSERT' then
  update public.icash_seller_recovery_attempts set responded_at=coalesce(responded_at,new.created_at),opted_out_at=case when public.icash_seller_contact_stop(new.body) then coalesce(opted_out_at,new.created_at) else opted_out_at end
   where account_id=t.account_id and thread_id=t.id and delivered_at is not null and delivered_at<=new.created_at;
  update public.icash_seller_gaps set state=case when public.icash_seller_contact_stop(new.body) then 'suppressed' else 'superseded' end,updated_at=now()
   where account_id=t.account_id and thread_id=t.id and state in ('open','queued','waiting') and created_at<new.created_at;
  -- A response ends the old reminder. The existing intake processes its content;
  -- it is not marked as a resolved question, accepted offer or signed agreement.
 elsif new.direction='outgoing' then
  if new.state='delivered' and new.provider_id is not null then
   update public.icash_seller_recovery_attempts set delivered_at=coalesce(delivered_at,new.last_delivery_at,now()) where account_id=t.account_id and message_id=new.id;
   update public.icash_seller_gaps set state='waiting',updated_at=now() where account_id=t.account_id and outgoing_id=new.id and state='queued';
   if not exists(select 1 from public.icash_seller_recovery_attempts where message_id=new.id) and new.body like '%?%'
    and exists(select 1 from public.icash_deal_files where id=t.deal_id and account_id=t.account_id and stage='draft') then
    perform public.icash_open_seller_gap(t.account_id,t.id,'text',new.id,'no_response','No reply to delivered question',coalesce(new.last_delivery_at,now()));
   end if;
  elsif new.state='needs_review' then
   update public.icash_seller_gaps set state='needs_review',updated_at=now() where account_id=t.account_id and outgoing_id=new.id and state in ('queued','waiting');
   perform public.icash_open_seller_gap(t.account_id,t.id,'text',new.id,'delivery_unknown','Delivery needs reconciliation; do not resend',now());
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_capture_buyer_scenario_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;screen uuid;previous text;turns jsonb;viewing text;coordination text;intent jsonb;
begin
 if new.direction<>'incoming' or new.state<>'received' then return new;end if;
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id and party='buyer' and retired_at is null;
 if not found or public.icash_buyer_package_data(t.account_id,t.deal_id) is null then return new;end if;
 select screening_id into screen from public.icash_deal_files where id=t.deal_id and account_id=t.account_id;if screen is null then return new;end if;
 select body into previous from public.icash_text_messages where account_id=t.account_id and thread_id=t.id and direction='outgoing' and state in ('accepted','delivered') and provider_id is not null and created_at<=new.created_at order by created_at desc,id desc limit 1;
 turns:=jsonb_build_array(jsonb_build_object('role','agent','message',coalesce(previous,'')),jsonb_build_object('role','user','message',new.body));
 viewing:=public.icash_buyer_viewing_quote(turns);coordination:=public.icash_buyer_coordination_quote(turns);intent:=public.icash_buyer_purchase_intent(turns);
 if viewing is null and coordination is null and intent is null then return new;end if;
 insert into public.icash_buyer_viewing_requests(account_id,deal_id,screening_id,thread_id,source,source_id,quote,viewing_quote,coordination_quote,timezone,kind)
 values(t.account_id,t.deal_id,screen,t.id,'text',new.id,coalesce(intent->>'quote',viewing,coordination),viewing,coordination,t.timezone,coalesce(intent->>'kind',case when viewing is null then 'buyer_followup' else 'viewing' end))
 on conflict(source,source_id) do update set viewing_quote=excluded.viewing_quote,coordination_quote=excluded.coordination_quote,
  kind=case when intent is null then icash_buyer_viewing_requests.kind else excluded.kind end,
  quote=case when intent is null then icash_buyer_viewing_requests.quote else excluded.quote end
 where icash_buyer_viewing_requests.state='needs_confirmation';
 return new;
end $function$
